import type { Metadata } from "next";
import Link from "next/link";

// PREVIEW INDEX — an internal gallery of the redesigned page templates.
// Not a live product page; kept out of search.
export const metadata: Metadata = {
  title: "Template redesign previews",
  robots: { index: false, follow: false },
};

type Item = { href: string; name: string; note: string; flag?: string };
type Group = { title: string; blurb: string; items: Item[] };

const GROUPS: Group[] = [
  {
    title: "Game servers",
    blurb: "The game-landing template — one combined direction plus the three originals it was merged from.",
    items: [
      { href: "/preview/game-combined", name: "Game landing — Combined", flag: "recommended", note: "The greatest-hits merge: cinematic key-art hero + live server panel, numbered reasons with a scroll spine + sticky 47s plan card, and a HUD deploy terminal. (Rust)" },
      { href: "/preview/game-cinematic", name: "Game landing — Cinematic (A)", note: "Full-bleed key art + floating animated live-ops panel. (Rust)" },
      { href: "/preview/game-editorial", name: "Game landing — Editorial (B)", note: "Magazine layout, ken-burns art, numbered reasons rail + sticky plan card. (Satisfactory)" },
      { href: "/preview/game-console", name: "Game landing — Command Deck (C)", note: "Art inside a glass HUD console + typing deploy terminal + telemetry gauges. (Palworld)" },
    ],
  },
  {
    title: "Content & SEO pages",
    blurb: "The templates behind the SEO content push.",
    items: [
      { href: "/preview/blog-post", name: "Blog post / listicle", note: "Editorial article: art banner, sticky TOC spine + reading progress, GEO quick-answer box, numbered item cards, spec/RAM tables, deploy CTA rails. (Best Rust plugins 2026)" },
      { href: "/preview/mods", name: "Game mods page", note: "Honest framing (real SFTP/file access, not a fake installer): animated file-manager upload, upload→drop→restart flow, per-game showcases." },
      { href: "/preview/comparison", name: "Competitor comparison", note: "Animated head-to-head scoreboard + elevated comparison table + free-migration CTA. (vs DigitalOcean)" },
      { href: "/preview/free-tier", name: "Free tier landing", note: "Aternos-alternative wedge: a free server that 'wakes on join', honest free-vs-paid, free→paid upgrade bridge. (Free Minecraft)" },
    ],
  },
  {
    title: "Core services",
    blurb: "The main product landing pages.",
    items: [
      { href: "/preview/ai-hosting", name: "AI / vibe-coding hosting", flag: "growth", note: "Describe → build → approve gate → deploy-in-47s flow, plus the Bolt/Lovable/v0/Cursor import wedge." },
      { href: "/preview/vps", name: "VPS main landing", note: "Animated deploy console + interactive plan configurator + NVMe/root buying story." },
      { href: "/preview/web-hosting", name: "Shared web hosting", note: "One-click WordPress install animation + 'no renewal price hikes' trust chart + cPanel-class screen." },
      { href: "/preview/business-email", name: "Business email", note: "Live inbox animation + deliverability ring + per-mailbox price comparison." },
      { href: "/preview/domains", name: "Domains", note: "Animated domain search + populating TLD price grid + all-in-one-account bundle." },
      { href: "/preview/nxcloud", name: "NxCloud (private cloud)", note: "Live files-sync dashboard + Sync/Office/Talk feature screens." },
    ],
  },
  {
    title: "Other page types",
    blurb: "Location, app-hosting, and tool templates.",
    items: [
      { href: "/preview/location", name: "Server location page", note: "Animated SEA latency map (Singapore → Jakarta/KL/Manila/…) with live ping readouts. (Singapore)" },
      { href: "/preview/app-hosting", name: "'Host X on a VPS' landing", note: "App identity + requirements table + self-host-vs-managed cost table + deploy terminal. (Ghost)" },
      { href: "/preview/tool", name: "Free tool page", note: "Interactive tool in a premium glass frame + related-tools rail + deploy CTA. (Minecraft server status)" },
    ],
  },
];

export default function PreviewIndex() {
  return (
    <div className="mx-auto max-w-5xl px-6 py-16">
      <p className="eyebrow mb-3" style={{ color: "var(--color-brand-400)" }}>Internal · not indexed</p>
      <h1 className="text-3xl font-extrabold tracking-tight text-white sm:text-4xl">
        Template redesign <span className="grad-text">previews</span>
      </h1>
      <p className="mt-3 max-w-2xl text-sm leading-relaxed text-slate-400">
        Fresh templates for every page category, built on one design system. Nothing here is live —
        every existing page is untouched. Pick the directions you like and I&apos;ll migrate the real
        pages onto them (per category). Best viewed on desktop; scroll each page to trigger its motion.
      </p>

      <div className="mt-12 space-y-14">
        {GROUPS.map((g) => (
          <section key={g.title}>
            <div className="mb-4 border-b border-white/[0.08] pb-3">
              <h2 className="text-lg font-bold text-white">{g.title}</h2>
              <p className="mt-1 text-xs text-slate-500">{g.blurb}</p>
            </div>
            <div className="grid gap-3 sm:grid-cols-2">
              {g.items.map((it) => (
                <Link
                  key={it.href}
                  href={it.href}
                  className="card group relative block transition-colors hover:border-brand-500/40"
                >
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-white group-hover:text-brand-300">{it.name}</span>
                    {it.flag && (
                      <span className="rounded-full border border-brand-400/40 bg-brand-500/15 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-brand-300">
                        {it.flag}
                      </span>
                    )}
                  </div>
                  <p className="mt-1.5 text-xs leading-relaxed text-slate-400">{it.note}</p>
                  <span className="mt-2 inline-block font-mono text-[11px] text-slate-500 group-hover:text-slate-300">
                    {it.href} →
                  </span>
                </Link>
              ))}
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}

