import type { MetadataRoute } from "next";
import { db } from "@/lib/db";
import { TOOL_SLUGS } from "@/lib/tools/catalog";
import { LANDING_SLUGS, REGION_LANDING_SLUGS } from "@/lib/marketing/locationLandings";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const now = new Date();

  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
    { path: "", priority: 1.0, freq: "weekly" },
    { path: "/features", priority: 0.8, freq: "monthly" },
    { path: "/vibe-coding", priority: 0.8, freq: "monthly" },
    { path: "/matrix", priority: 0.9, freq: "monthly" },
    { path: "/pricing", priority: 0.9, freq: "weekly" },
    { path: "/vps", priority: 0.8, freq: "monthly" },
    { path: "/web-hosting", priority: 0.8, freq: "monthly" },
    { path: "/domains", priority: 0.8, freq: "monthly" },
    // Core product / landing pages that shipped after the original list was
    // written — all indexable (unlike the noindex /v2–/v8 homepage previews).
    { path: "/business-email", priority: 0.8, freq: "monthly" },
    { path: "/game-servers", priority: 0.8, freq: "monthly" },
    { path: "/game-servers/mods", priority: 0.7, freq: "monthly" },
    { path: "/free-minecraft", priority: 0.8, freq: "monthly" },
    { path: "/servers", priority: 0.7, freq: "daily" },
    { path: "/block-storage", priority: 0.8, freq: "monthly" },
    { path: "/nxcloud", priority: 0.7, freq: "monthly" },
    { path: "/docs", priority: 0.6, freq: "weekly" },
    { path: "/migrate", priority: 0.7, freq: "monthly" },
    { path: "/security", priority: 0.6, freq: "monthly" },
    { path: "/developers", priority: 0.6, freq: "monthly" },
    { path: "/affiliate", priority: 0.5, freq: "monthly" },
    { path: "/compare", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-a2hosting", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-bluehost", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-cloudways", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-godaddy", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-hostgator", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-ionos", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-kamatera", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-namecheap", priority: 0.7, freq: "monthly" },
    // "Move from X to Nxeon" migration-intent pages — paired 1:1 with the
    // vps-vs-X comparison pages above (see app/(marketing)/migrate-from-*).
    { path: "/migrate-from-a2hosting", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-bluehost", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-cloudways", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-digitalocean", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-godaddy", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-hostgator", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-hostinger", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-ionos", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-kamatera", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-namecheap", priority: 0.7, freq: "monthly" },
    // Competitor "alternative" comparison pages.
    { path: "/hetzner-alternative", priority: 0.7, freq: "monthly" },
    { path: "/contabo-alternative", priority: 0.7, freq: "monthly" },
    { path: "/vultr-alternative", priority: 0.7, freq: "monthly" },
    { path: "/linode-alternative", priority: 0.7, freq: "monthly" },
    { path: "/ovh-alternative", priority: 0.7, freq: "monthly" },
    { path: "/aws-lightsail-alternative", priority: 0.7, freq: "monthly" },
    // High-intent "host X on a VPS" use-case pages.
    { path: "/wordpress-vps-hosting", priority: 0.8, freq: "monthly" },
    { path: "/docker-hosting", priority: 0.8, freq: "monthly" },
    { path: "/n8n-hosting", priority: 0.8, freq: "monthly" },
    { path: "/nodejs-hosting", priority: 0.8, freq: "monthly" },
    { path: "/nextcloud-hosting", priority: 0.8, freq: "monthly" },
    { path: "/vpn-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/discord-bot-hosting", priority: 0.8, freq: "monthly" },
    { path: "/minecraft-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/rust-server-hosting", priority: 0.7, freq: "monthly" },
    // Buyer-intent game-server + gaming-VPS landing pages (high-impression queries).
    { path: "/gaming-vps", priority: 0.8, freq: "monthly" },
    { path: "/palworld-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/valheim-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/ark-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/7-days-to-die-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/project-zomboid-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/v-rising-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/enshrouded-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/satisfactory-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/terraria-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/cs2-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/garrys-mod-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/fivem-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/factorio-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/conan-exiles-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/unturned-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/the-forest-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/sons-of-the-forest-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/minecraft-bedrock-server-hosting", priority: 0.7, freq: "monthly" },
    // Budget + location intent pages.
    { path: "/cheap-vps-hosting", priority: 0.8, freq: "monthly" },
    { path: "/affordable-vps-hosting", priority: 0.7, freq: "monthly" },
    { path: "/best-value-vps", priority: 0.7, freq: "monthly" },
    { path: "/free-vps", priority: 0.7, freq: "monthly" },
    { path: "/singapore-vps-hosting", priority: 0.7, freq: "monthly" },
    { path: "/about", priority: 0.5, freq: "monthly" },
    { path: "/contact", priority: 0.5, freq: "monthly" },
    { path: "/blog", priority: 0.7, freq: "weekly" },
    { path: "/tools", priority: 0.7, freq: "weekly" },
    ...TOOL_SLUGS.map((slug) => ({
      path: `/tools/${slug}`,
      priority: 0.6,
      freq: "monthly" as const,
    })),
    { path: "/status", priority: 0.4, freq: "daily" },
    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
  ];

  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
    url: `${APP_URL}${r.path}`,
    lastModified: now,
    changeFrequency: r.freq,
    priority: r.priority,
  }));

  // Programmatic "(location) (service)" landing pages (lib/marketing/locationLandings.ts).
  for (const slug of LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.7,
    });
  }

  // Region-tier umbrella landing pages above the city matrix (same file) —
  // e.g. /usa-vps-hosting, /europe-game-server-hosting. Slightly higher
  // priority than a single city page since they target more generic,
  // higher-volume queries ("american vps hosting").
  for (const slug of REGION_LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.75,
    });
  }

  // Published blog posts (model may not be migrated yet — access defensively).
  try {
    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
    const posts = blogModel
      ? await blogModel.findMany({
          where: { published: true },
          select: { slug: true, updatedAt: true },
          orderBy: { publishedAt: "desc" },
        })
      : [];
    for (const p of posts) {
      entries.push({
        url: `${APP_URL}/blog/${p.slug}`,
        lastModified: p.updatedAt,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  } catch {
    // blogPost model not migrated yet — skip.
  }

  // Public free-Minecraft server pages (/servers/[subdomain]) — same opt-in
  // gate as the page itself (isPublic + READY), so the sitemap never points a
  // crawler at a server whose owner hasn't chosen to list it. Uncapped here
  // (unlike the /servers directory page, which caps its display at 48) since
  // a sitemap listing more entries than a page shows is normal and desirable
  // for indexing — every public server should be crawlable even if it's
  // beyond the directory's newest-48 display cap.
  try {
    const freeServers = await db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" },
      select: { subdomain: true, createdAt: true },
    });
    for (const s of freeServers) {
      entries.push({
        url: `${APP_URL}/servers/${s.subdomain}`,
        lastModified: s.createdAt,
        changeFrequency: "weekly",
        priority: 0.5,
      });
    }
  } catch {
    // Defensive, matching the blogPost handling above — should never actually
    // throw since FreeMinecraftServer ships in this same migration.
  }

  return entries;
}

