"use client";

import { useState } from "react";
import { AppLogo } from "@/components/ui/AppLogo";

export type CatalogGroup = { key: string; label: string; items: string[] };

/** Map a catalog item's display name to a logo family AppLogo understands. */
function logoFamily(name: string): string {
  const n = name.toLowerCase();
  const table: [string, string][] = [
    ["ubuntu", "ubuntu"], ["debian", "debian"], ["almalinux", "almalinux"],
    ["rocky", "rocky"], ["fedora", "fedora"], ["centos", "centos"], ["arch", "arch"],
    ["alpine", "alpine"], ["kali", "kali"], ["suse", "opensuse"],
    ["cpanel", "cpanel"], ["plesk", "plesk"], ["cyberpanel", "cyberpanel"],
    ["webmin", "webmin"], ["cloudpanel", "cloudpanel"], ["aapanel", "aapanel"],
    ["hestia", "hestiacp"],
    ["docker", "docker"], ["wordpress", "wordpress"], ["nextcloud", "nextcloud"],
    ["ghost", "ghost"], ["node", "nodejs"], ["caddy", "caddy"],
    ["wireguard", "wireguard"], ["openvpn", "openvpn"], ["gitea", "gitea"],
    ["jellyfin", "jellyfin"], ["pi-hole", "pihole"], ["pihole", "pihole"],
    ["grafana", "grafana"], ["portainer", "portainer"], ["vaultwarden", "vaultwarden"],
    ["uptime", "uptimekuma"],
  ];
  for (const [k, fam] of table) if (n.includes(k)) return fam;
  return name; // AppLogo falls back to the first letter
}

function Tile({ name }: { name: string }) {
  return (
    <div className="group flex items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3 transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30 hover:bg-white/[0.05] hover:shadow-[0_8px_24px_-12px_rgb(111_71_245_/_0.5)]">
      <AppLogo family={logoFamily(name)} name={name} size={36} />
      <span className="truncate text-sm font-medium text-slate-200">{name}</span>
    </div>
  );
}

export function DeployCatalog({ groups }: { groups: CatalogGroup[] }) {
  const [active, setActive] = useState(groups[0]?.key ?? "");
