"use client";

import { useState } from "react";
import Link from "next/link";
import { IconCheck } from "./icons";
import { planTip, planAudience } from "./planTips";
import { termPriceCents, ANNUAL_TERM_MONTHS } from "@/lib/billing-terms";
import { useDisplayMoney } from "@/components/currency/CurrencyContext";

export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

function planFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    "Full root access",
    "Free DDoS protection",
  ];
}

export function PricingGrid({ plans, annualPct = 0 }: { plans: PlanCard[]; annualPct?: number }) {
  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
  const money = useDisplayMoney();
  // Billing toggle — Annual is on by default when it's a real discount, so the
  // headline price shows the better-value figure first. Switching to Monthly shows
  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
  // the SAME formula checkout charges — displayed === charged.
  const annualAvailable = annualPct > 0;
  const [annual, setAnnual] = useState(true);
  const showAnnual = annual && annualAvailable;

  // Highlight the middle plan (by position) as "Most popular"; the top (most
  // expensive) plan gets a "Best value / most resources" anchor so the mid tier
  // reads as the smart buy.
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
  const topIdx = plans.length >= 3 ? plans.length - 1 : -1;
  const fromCents = plans.length ? Math.min(...plans.map((p) => p.priceCents)) : 0;

/**
 * Smart, spec-derived guidance for a plan. Given a plan's resources, returns a
 * short "great for…" line so visitors can self-select the right box at a glance.
 * Pure function — safe on the server and the client.
 */

export type PlanLike = {
  cpuCores: number;
  ramMB: number;
  diskGB: number;
};

/** One-line "great for…" recommendation derived from a plan's RAM (and cores). */
export function planTip(plan: PlanLike): string {
  const ram = plan.ramMB;
  if (ram <= 2048) return "Personal sites, dev/staging, bots, VPNs";
  if (ram <= 4096) return "WordPress & WooCommerce, small game servers, CI runners";
  if (ram <= 8192) return "Busy sites, databases, Docker stacks, small multiplayer servers";
  return "High-traffic apps, big databases, multiple sites, heavy workloads";
}

/** A tighter one/two-word audience label, handy for badges. */
export function planAudience(plan: PlanLike): string {
  const ram = plan.ramMB;
  if (ram <= 2048) return "Starter";
  if (ram <= 4096) return "Growth";
  if (ram <= 8192) return "Scale";
  return "Power";
}

