import type { Metadata } from "next";
import Link from "next/link";
import { db } from "@/lib/db";
import { GAME_FAMILIES } from "@/lib/games";
import { annualDiscountPct } from "@/lib/annual-discount";
import { planTip } from "@/components/marketing/planTips";
import { Reveal } from "@/components/marketing/Reveal";
import { DeployCatalog, type CatalogGroup } from "@/components/marketing/DeployCatalog";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { VpsLanding } from "@/components/marketing/vpstemplate/VpsLanding";
import type { ConfigStop } from "@/components/marketing/vpstemplate/data";
import { FaqJsonLd, ProductJsonLd } from "@/components/marketing/StructuredData";

// ReviewBadges + the plan/catalog data all read live DB state — render
// dynamically, matching the pre-redesign /vps page.
export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "VPS Hosting",
  description:
    "High-performance NVMe cloud VPS with full root access, a dedicated IPv4, snapshots, backups, DDoS protection, and one-click apps. Deployed from Singapore in under a minute.",
  alternates: { canonical: "/vps" },
};

/** Format cents as a dollar string ("$5", "$5.99") — matches the pricing cards. */
const money = (cents: number) => {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
};

const CATEGORY_LABELS: Record<string, string> = {
  PLAIN_OS: "Operating systems",
  CONTROL_PANEL: "Control panels",
  APPLICATION: "One-click apps",
};

const FALLBACK: Record<string, string[]> = {
  PLAIN_OS: ["Ubuntu 24.04", "Debian 13", "AlmaLinux 9", "Rocky Linux 9", "Fedora"],
  CONTROL_PANEL: ["cPanel", "Plesk", "CyberPanel", "Webmin", "CloudPanel", "aaPanel", "HestiaCP"],
  APPLICATION: ["Docker", "WordPress", "Nextcloud", "Ghost", "n8n", "PostgreSQL"],
};

const FAQ = [
  { q: "How fast is provisioning?", a: "Servers are automated end-to-end and typically deploy in under 60 seconds — NVMe clone, cloud-init, IP allocation, and firewall rules all applied automatically." },
  { q: "Do I get full root access?", a: "Yes. Every VPS gives you complete root over SSH plus a dedicated IPv4 address. Install anything, tune the kernel, and run whatever you like." },
  { q: "Can I resize later?", a: "Absolutely. Bump vCPU, RAM, and disk from the dashboard as your workload grows — no need to rebuild from scratch." },
  { q: "Where are the servers located?", a: "All servers run from our Singapore data center — a low-latency home base for users across Asia-Pacific, with fast, well-peered connectivity." },
  { q: "How does billing work?", a: "Prepaid from a wallet balance in your account. Top up, servers auto-renew monthly, and you can cancel anytime — billing stops at the end of the period." },
];

export default async function VpsPage() {
  const [plans, templates, annualPct] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    // Live admin annual discount, so the pricing cards can surface the real annual
    // $/mo and % saved (DB-fed, the same rate checkout charges).
    annualDiscountPct(),
  ]);

  const OS_FAMILY_LABEL: Record<string, string> = {
    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
  };
  // Game-server families are shown on their own dedicated Game Server product
  // page, not here — without this filter every game (ARK, Satisfactory, V
  // Rising, ...) would double up inside the "One-click apps" showcase, since
  // they share the OsTemplate APPLICATION category with genuine apps like
  // Docker/WordPress. Sourced from lib/games.ts, the single canonical list.
  const gameFamilies = new Set<string>(GAME_FAMILIES);
  const byCat = (cat: string) => {
    const list = templates.filter((t) => t.category === cat && !(cat === "APPLICATION" && gameFamilies.has(t.family)));
    if (cat === "PLAIN_OS") {
      const seen = new Set<string>();
      const fams: string[] = [];
      for (const t of list) {
        const fam = (t.family || t.name).toLowerCase();
        if (seen.has(fam)) continue;
        seen.add(fam);
        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
      }
      return fams.length ? fams : FALLBACK[cat];
    }
    const live = list.map((t) => t.name);
    return live.length ? live : FALLBACK[cat];
  };
  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
    key: cat,
    label: CATEGORY_LABELS[cat],
    items: byCat(cat),
  }));
  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);

  // Real plans, mapped to the template's ConfigStop shape so the interactive
  // configurator drives off live DB pricing/specs instead of illustrative
  // preview numbers. Same "middle plan is Popular" heuristic as PricingGrid.
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
  const configStops: ConfigStop[] = plans.map((p, i) => ({
    id: p.slug,
    tier: p.name,
    ram: Math.round(p.ramMB / 1024),
    vcpu: p.cpuCores,
    nvme: p.diskGB,
    bandwidth: p.bandwidthTB,
    price: money(p.priceCents),
    popular: i === popularIdx,
    blurb: planTip(p),
  }));

  return (
    <>
      <FaqJsonLd items={FAQ} />
      {plans.length > 0 && <ProductJsonLd plans={plans} />}
      <VpsLanding reviewBadges={<ReviewBadges />} configStops={configStops} />

      {/* Deploy catalog — real one-click OS/control-panel/app images from the
          DB. The template's "everything included" grid names a couple of
          examples but doesn't browse the full catalog, so it's kept as its
          own section in the established brand system (Section/SectionTitle),
          right where visitors expect it after the configurator. */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="Deploy anything"
          title="Your stack, ready on first boot"
          sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps — then customise everything with full root access.`}
        />
        <Reveal className="mt-12">
          <DeployCatalog groups={groups} />
        </Reveal>
        <p className="mt-8 text-center text-sm text-slate-400">
          Running WordPress? See our guide to the{" "}
          <Link href="/blog/best-vps-for-wordpress" className="font-medium text-brand-300 hover:text-brand-200">
            best VPS for WordPress
          </Link>
          .
        </p>
      </Section>

      {/* FAQ */}
      <Section size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {FAQ.map((f) => (
            <div key={f.q} className="card">
              <h3 className="text-base font-semibold text-white">{f.q}</h3>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </div>
          ))}
        </div>
      </Section>
    </>
  );
}

