import type { Metadata } from "next";
import { db } from "@/lib/db";
import { EmailLanding } from "@/components/marketing/emailtemplate/EmailLanding";
import { PRICE_ANCHORS, type EmailPlan, type PriceAnchor } from "@/components/marketing/emailtemplate/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";

// Tiers are sourced from the same active db.emailPlan records the portal sells
// at checkout — mirroring how pricing/vps pages read their plans from the DB.
export const dynamic = "force-dynamic";

const DESCRIPTION =
  "Professional email on your own domain (you@yourcompany.com) that actually lands in the inbox — SPF, DKIM, and DMARC configured and verified for you, unlimited aliases, free migration, and honest flat-tier pricing.";

export const metadata: Metadata = {
  title: "Business Email",
  description: DESCRIPTION,
  alternates: { canonical: "/business-email" },
  openGraph: {
    type: "website",
    title: "Business Email on your own domain",
    description: DESCRIPTION,
  },
};

/** Format cents as a dollar string ("$1.99", "$25"). */
function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

// The db.emailPlan model carries name / mailboxes / storageGB / priceCents /
// termMonths but no marketing copy, so we derive the tagline and feature bullets
// here. Tagline falls back gracefully for admin-created tiers with novel names.
const TAGLINES: Record<string, string> = {
  Starter: "A professional inbox for you.",
  Business: "Email for a small team.",
  Pro: "Room for the whole company.",
};

type EmailPlanRecord = {
  name: string;
  mailboxes: number;
  storageGB: number;
  priceCents: number;
  termMonths: number;
};

/** Build the template's plan-card view-model from a db.emailPlan record. The
 * real product sells flat tiers with a bundled mailbox count (not a genuine
 * per-mailbox unit price), so `unit` is "/mo" here — see EmailPlan's doc
 * comment in data.ts. */
function tierFromPlan(p: EmailPlanRecord, popular: boolean): EmailPlan {
  return {
    id: p.name.toLowerCase().replace(/\s+/g, "-"),
    tier: p.name,
    price: money(p.priceCents),
    unit: p.termMonths > 1 ? `/${p.termMonths}mo` : "/mo",
    storage: `${p.storageGB} GB / mailbox`,
    popular,
    blurb: TAGLINES[p.name] ?? "Professional email on your own domain.",
    features: [
      `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}`,
      `${p.storageGB} GB per mailbox`,
      "Webmail + IMAP/SMTP",
      "Spam & virus filtering",
    ],
  };
}

const FAQ = [
  {
    q: "Can I use my own domain?",
    a: "Yes — every plan is you@yourcompany.com on your own domain, with unlimited aliases and a catch-all so the whole team looks like one brand.",
  },
  {
    q: "Will my email land in the inbox instead of spam?",
    a: "SPF, DKIM, and DMARC are configured and verified for you the moment your domain connects, so your mail arrives with a clean sender reputation instead of a spam-folder tax.",
  },
  {
    q: "How is it priced?",
    a: "Simple flat monthly plans, each with a bundled mailbox count and storage allowance — no setup fees, cancel anytime.",
  },
  {
    q: "Do you migrate my existing email?",
    a: "Yes. We add the MX, SPF, DKIM, and DMARC records for you and migrate your old mail across for free.",
  },
];

export default async function BusinessEmailPage() {
  const plans = await db.emailPlan.findMany({
    where: { active: true },
    orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
  });
  // Highlight the middle tier as "Most popular" when there is more than one.
  const popularIndex = plans.length > 1 ? Math.floor((plans.length - 1) / 2) : -1;
  const templatePlans: EmailPlan[] = plans.map((p, i) => tierFromPlan(p, i === popularIndex));

  // Real vs-competitor anchor row for Nxeon, computed as an effective
  // per-mailbox rate off the cheapest active tier — the two competitor rows
  // (Google Workspace, Zoho) stay the static, labelled list prices from the
  // template; only our own number is replaced with something we can stand
  // behind.
  const cheapest = plans.length ? plans.reduce((a, b) => (a.priceCents <= b.priceCents ? a : b)) : null;
  const priceAnchors: PriceAnchor[] = cheapest
    ? PRICE_ANCHORS.map((a) =>
        a.name === "Nxeon Business Email"
          ? {
              ...a,
              price: money(Math.round(cheapest.priceCents / Math.max(1, cheapest.mailboxes))),
              unit: "/mailbox/mo*",
              note: `${cheapest.name} plan · ${money(cheapest.priceCents)}/mo for ${cheapest.mailboxes} mailbox${cheapest.mailboxes === 1 ? "" : "es"}`,
            }
          : a,
      )
    : PRICE_ANCHORS;

  return (
    <>
      <FaqJsonLd items={FAQ} />
      {plans.length > 0 && (
        <ProductOffersJsonLd
          name="Nxeon Business Email"
          description="Professional email hosting on your own domain — SPF/DKIM/DMARC configured for you, webmail, IMAP/SMTP, spam and virus filtering, and free migration."
          url={`${APP_URL}/business-email`}
          offers={plans.map((p) => ({ name: p.name, price: p.priceCents / 100 }))}
        />
      )}
      <EmailLanding reviewBadges={<ReviewBadges />} plans={templatePlans} priceAnchors={priceAnchors} />
    </>
  );
}

