import type { Metadata } from "next";
import { DomainsLanding } from "@/components/marketing/domainstemplate/DomainsLanding";
import type { TldRow } from "@/components/marketing/domainstemplate/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";

export const metadata: Metadata = {
  title: "Domains",
  description:
    "Search, register, and manage domains — with free WhoisGuard privacy, full DNS management, and one-click pointing at your Nxeon VPS.",
  alternates: { canonical: "/domains" },
};

const FAQ = [
  { q: "Which extensions can I register?", a: "Popular TLDs like .com, .net, .io, .dev, .app, .co, .ai and many more. Search any name to see live availability and pricing once registration is enabled on your account." },
  { q: "Is domain privacy really free?", a: "Yes. WhoisGuard privacy protection is included at no extra cost for every eligible domain, keeping your contact details off the public WHOIS record." },
  { q: "Can I point a domain at my VPS?", a: "In one click. From the dashboard, choose a server and we configure the DNS records automatically so your domain resolves to your VPS." },
  { q: "Do you handle renewals?", a: "Enable auto-renew and domains renew automatically from your wallet balance before they expire. You will always get reminders in advance." },
  { q: "Can I transfer a domain in?", a: "Yes — inbound transfers are supported for eligible TLDs. Unlock the domain at your current registrar and grab the auth code to start." },
];

function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/** A couple of hand-picked notes for the well-known extensions — everything
 * else in the real catalog just shows the plain "from $X/yr" price. */
const TLD_NOTES: Record<string, string> = {
  ".com": "The one people trust",
  ".io": "Loved by tech + startups",
  ".ai": "For anything AI",
  ".dev": "Built-in HTTPS",
  ".shop": "Sell online",
  ".co": "Short + brandable",
  ".xyz": "Cheapest to start",
  ".in": "India",
};

export default function DomainsPage() {
  // Real pricing rail — the template's illustrative PRICING_TLDS swapped for
  // the same POPULAR_TLDS catalog the live hero search and JSON-LD already
  // use, so every number on the page traces back to one source of truth.
  const pricingTlds: TldRow[] = POPULAR_TLDS.slice(0, 8).map((t, i) => ({
    tld: t.tld,
    price: money(t.fromCents),
    note: TLD_NOTES[t.tld],
    hot: i === 0,
  }));

  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Domains"
        description="Register or transfer domains with free WHOIS privacy and managed DNS, on the same account as your VPS, hosting and email."
        url={`${APP_URL}/domains`}
        offers={POPULAR_TLDS.map((t) => ({ name: `${t.tld} domain`, price: t.fromCents / 100 }))}
      />
      <FaqJsonLd items={FAQ} />
      <DomainsLanding reviewBadges={<ReviewBadges />} pricingTlds={pricingTlds} />
    </>
  );
}

