input.command:
cd /opt/nxeon-staging && for f in "app/(marketing)/vps/page.tsx" "app/(marketing)/web-hosting/page.tsx" "app/(marketing)/business-email/page.tsx" "app/(marketing)/domains/page.tsx" "app/(marketing)/nxcloud/page.tsx"; do
echo "=== $f ==="
node -e '
const fs = require("fs");
const path = process.argv[1];
const src = fs.readFileSync(path, "utf8");
const importLines = [...src.matchAll(/import\s+(?:type\s+)?\{([^}]+)\}\s+from/g)];
for (const m of importLines) {
  const names = m[1].split(",").map(s => s.trim().split(" as ").pop().replace(/^type\s+/,"").trim()).filter(Boolean);
  for (const n of names) {
    const re = new RegExp("\\b" + n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b", "g");
    const count = (src.match(re) || []).length;
    if (count <= 1) console.log("UNUSED?", n);
  }
}
' "$f"
done
